const results = $input.first().json.results;
const items = [];

results.forEach(item => {
  items.push({
    json: {
      title: item.product_description || 'No title',
      company: item.recalling_firm || 'Unknown',
      date: item.report_date || 'Unknown',
      reason: item.reason_for_recall || 'Not specified',
      classification: item.classification || 'Unknown',
      status: item.status || 'Unknown',
      country: item.country || 'Unknown',
      city: item.city || 'Unknown'
    }
  });
});

return items.slice(Object, 5);

const items = $input.all();
const prevItems = $('Code in JavaScript').all();
let recallRows = '';

items.forEach((item, index) => {
    const summary = item.json.output || 
                    item.json.text || 
                    'No summary available';

    const prev = prevItems[index] ? prevItems[index].json : {};
    const classColor = (prev.classification || '').includes('I') ? '#e74c3c' : '#e67e22';
    const fdaLink = 'https://www.google.com/search?q=' + encodeURIComponent('FDA recall ' + (prev.company || '') + ' ' + (prev.date || ''));

    recallRows += '<div style="background:#ffffff; border-left:5px solid #c0392b; padding:18px; margin-bottom:18px; border-radius:6px; box-shadow:0 2px 6px rgba(0,0,0,0.08);">' +
                  '<h3 style="color:#c0392b; margin:0 0 10px 0; font-size:15px;">&#128204; ' + (prev.title || 'Recall #' + (index + 1)) + '</h3>' +
                  '<p style="margin:0 0 6px 0; font-size:13px; color:#555;">' +
                  '&#127970; <b>Company:</b> ' + (prev.company || 'N/A') + ' &nbsp;|&nbsp; ' +
                  '&#128197; <b>Date:</b> ' + (prev.date || 'N/A') + ' &nbsp;|&nbsp; ' +
                  '<b style="color:' + classColor + ';">&#9888; Class: ' + (prev.classification || 'N/A') + '</b>' +
                  '</p>' +
                  '<p style="margin:0 0 12px 0; font-size:12px; color:#888;">&#128205; ' + (prev.city || '') + ', ' + (prev.country || '') + '</p>' +
                  '<p style="margin:0 0 12px 0; color:#333; line-height:1.7; font-size:13px; border-top:1px solid #eee; padding-top:10px;">&#129302; <b>AI Summary:</b> ' + summary + '</p>' +
                  '<a href="' + fdaLink + '" style="display:inline-block; background:#c0392b; color:white; padding:7px 14px; border-radius:4px; text-decoration:none; font-size:12px;">&#128269; Search This Recall on Google</a>' +
                  '</div>';
});

const today = new Date().toLocaleDateString('en-IN', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

const html = '<!DOCTYPE html><html><head><meta charset="utf-8"></head>' +
             '<body style="font-family:Arial,sans-serif; max-width:800px; margin:auto; padding:20px; background:#f4f6f8;">' +
             '<div style="background:#c0392b; padding:25px; border-radius:8px; margin-bottom:25px;">' +
             '<h1 style="color:white; margin:0; font-size:22px;">&#128680; FDA Drug Enforcement Alert</h1>' +
             '<p style="color:#ffcccc; margin:8px 0 0 0; font-size:14px;">&#128197; ' + today + '</p>' +
             '<a href="https://www.fda.gov/safety/recalls-market-withdrawals-safety-alerts" style="display:inline-block; margin-top:12px; background:white; color:#c0392b; padding:7px 14px; border-radius:4px; text-decoration:none; font-size:12px; font-weight:bold;">&#127760; View Full FDA Database</a>' +
             '</div>' +
             '<div style="background:#fff3f3; border:1px solid #f5c6c6; padding:15px; border-radius:6px; margin-bottom:20px;">' +
             '<p style="margin:0; font-size:16px; color:#c0392b;"><b>&#9888; Total Recalls Today: ' + items.length + '</b></p>' +
             '</div>' +
             recallRows +
             '<div style="margin-top:25px; padding:15px; background:#f8f9fa; border-radius:6px; text-align:center;">' +
             '<p style="color:#888; font-size:11px; margin:0;">&#128269; Source: FDA OpenFDA API &nbsp;|&nbsp; &#129302; Automated by AI Regulatory Monitor &nbsp;|&nbsp; ' + today + '</p>' +
             '</div>' +
             '</body></html>';

return [{ json: { html: html, subject: 'FDA Alert ' + items.length + ' Recalls | ' + today } }];

